    fillLineX(2, 8, deckY, 5, logX);
    fillLineX(2, 8, deckY, 8, logX);
    fillLineZ(2, deckY, 2, 8, logZ);
    fillLineZ(5, deckY, 2, 8, logZ);
    fillLineZ(8, deckY, 2, 8, logZ);
    fillRectXZ(2, 2, 8, 8, deckY, planks);

    // High North Drying Crossbars
    fillLineX(2, 8, 10, 2, strippedLogX);
    fillLineX(2, 8, 13, 2, logX);
    buildDryingRackTier(2, 2, 8, 2, 13, 3);
    buildDryingRackTier(2, 2, 8, 2, 10, 2);

    // South Salting Gable Canopy
    for (let z = 5; z <= 8; z++) {
      set(1, 9, z, roofStairsE);
      set(2, 10, z, roofSolid);
      set(3, 11, z, roofStairsE);
      set(4, 11, z, roofSolid);
