    set(5, 10, 5, lanternCeil);

    // North Stair Approach
    const gyN = getGroundY(5, 1);
    buildRamp(5, 1, 5, 2, deckY, stairsS);

  } else if (variant === 8) {
    // VARIANT 8: Carapace Ridge Overhang Rack & Guy-Line Anchors
    const deckY = 7;
    const posts = [
      [2, 2, 13], [5, 2, 13], [8, 2, 13],
      [2, 6, deckY], [5, 6, deckY], [8, 6, deckY]
    ];
    for (const [px, pz, topY] of posts) buildPost(px, pz, topY);

    fillRectXZ(2, 2, 8, 7, deckY, planks);
    addDeckBracing(2, 8, 2, 7, deckY);

    // Diagonal Heavy Knee Braces on Deck Overhang
    for (let x of [2, 5, 8]) {
      set(x, deckY - 1, 1, stairsSTop);
      set(x, deckY - 1, 7, stairsNTop);
    }

    // High Curved Drying Arch across North
    fillLineX(2, 8, 13, 2, logX);
    fillLineX(2, 8, 11, 2, strippedLogX);
    for (let x = 3; x <= 7; x++) {
      set(x, 12, 2, cobweb);
      set(x, 10, 2, (x % 2 === 0) ? cobweb : chain);
      set(x, 9, 2, (x % 2 === 0) ? driedKelp : curedFish);
    }
    set(5, 12, 2, lanternCeil);

    // Guy-Line Anchors to Stone Plinths
    const gySW = getGroundY(1, 8);
    set(1, gySW, 8, stonePrimary);
    set(1, gySW + 1, 8, stoneWall);
    set(2, deckY, 7, fence);

    const gySE = getGroundY(9, 8);
    set(9, gySE, 8, stonePrimary);
    set(9, gySE + 1, 8, stoneWall);
    set(8, deckY, 7, fence);

    // Salting Station on Deck
    set(3, deckY + 1, 5, barrelUp);
    set(4, deckY + 1, 5, saltCrate);
    set(6, deckY + 1, 5, cauldron);
    set(7, deckY + 1, 5, barrelUp);

    // South Stair Descent
    const gyS = getGroundY(5, 8);
    buildRamp(5, 8, 5, 6, deckY, stairsN);

  } else {
    // VARIANT 9: Fisher's Smokehouse & High Air-Drying Loft
    const deckY = 7;
    const posts = [
      [2, 2, 12], [5, 2, 12], [2, 6, 12], [5, 6, 12],
      [8, 2, 12], [8, 6, 12], [8, 8, deckY], [5, 8, deckY], [2, 8, deckY]
    ];
    for (const [px, pz, topY] of posts) buildPost(px, pz, topY);

    fillRectXZ(2, 2, 8, 8, deckY, planks);

    // Stone Smokehouse Foundation (West)
    for (let x = 2; x <= 5; x++) {
      for (let z = 2; z <= 6; z++) {
        const gy = getGroundY(x, z);
        for (let y = gy; y <= deckY; y++) {
          if (x === 2 || x === 5 || z === 2 || z === 6) {
            set(x, y, z, stonePrimary);
          } else {
            set(x, y, z, plinth);
          }
        }
      }
    }

    // Smokehouse Upper Loft & Chimney
    for (let z = 2; z <= 6; z++) {
      set(1, 10, z, roofStairsE);
      set(2, 11, z, roofSolid);
      set(3, 12, z, roofStairsE);
      set(4, 12, z, roofSolid);
      set(5, 11, z, roofStairsW);
      set(6, 10, z, roofStairsW);
    }
    set(3, 13, 4, stoneWall); // Chimney cap

    // East Outdoor Drying Poles
    fillLineZ(8, 12, 2, 6, logZ);
    buildDryingRackTier(8, 2, 8, 6, 12, 3);
    set(7, deckY + 1, 4, barrelUp);
    set(7, deckY + 1, 5, saltCrate);
    set(7, deckY + 1, 7, barrelN);

    // Entry Steps on North
    const gyN = getGroundY(7, 1);
    buildRamp(7, 1, 7, 2, deckY, stairsS);
  }

  // --- Foundation & Connectivity Enforcement ---
  function getNeighbors(x, y, z) {
    const n = [];
    if (x > 0) n.push([x - 1, y, z]);
    if (x < W - 1) n.push([x + 1, y, z]);
    if (y > 0) n.push([x, y - 1, z]);
    if (y < H - 1) n.push([x, y + 1, z]);
    if (z > 0) n.push([x, y, z - 1]);
    if (z < D - 1) n.push([x, y, z + 1]);
    return n;
  }

  function ensureSingleConnectedSolid() {
    const visited = Array.from({ length: W }, () =>
      Array.from({ length: H }, () =>
        new Array(D).fill(false)
      )
    );

    const components = [];

    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        for (let z = 0; z < D; z++) {
          if (world[x][y][z] !== null && !visited[x][y][z]) {
            const comp = [];
            const queue = [[x, y, z]];
            visited[x][y][z] = true;

            while (queue.length > 0) {
              const [cx, cy, cz] = queue.shift();
              comp.push([cx, cy, cz]);

              for (const [nx, ny, nz] of getNeighbors(cx, cy, cz)) {
                if (world[nx][ny][nz] !== null && !visited[nx][ny][nz]) {
                  visited[nx][ny][nz] = true;
                  queue.push([nx, ny, nz]);
                }
              }
            }
            components.push(comp);
          }
        }
      }
    }

    if (components.length === 0) return;

    components.sort((a, b) => b.length - a.length);
    const mainComp = components[0];

    // Bridge or prune stray secondary components
    for (let i = 1; i < components.length; i++) {
      const comp = components[i];
      let minDist = 999;
      let bestStart = null;
      let bestTarget = null;

      for (const [cx, cy, cz] of comp) {
        for (const [mx, my, mz] of mainComp) {
          const d = Math.abs(cx - mx) + Math.abs(cy - my) + Math.abs(cz - mz);
          if (d < minDist) {
            minDist = d;
            bestStart = [cx, cy, cz];
            bestTarget = [mx, my, mz];
          }
        }
      }

      if (minDist <= 3 && bestStart && bestTarget) {
        let [cx, cy, cz] = bestStart;
        const [tx, ty, tz] = bestTarget;
        while (cx !== tx || cy !== ty || cz !== tz) {
          if (cx < tx) cx++;
          else if (cx > tx) cx--;
          else if (cz < tz) cz++;
          else if (cz > tz) cz--;
          else if (cy < ty) cy++;
          else if (cy > ty) cy--;

          if (world[cx][cy][cz] === null) {
            world[cx][cy][cz] = fence;
          }
        }
        for (const pt of comp) mainComp.push(pt);
      } else {
        for (const [cx, cy, cz] of comp) {
          world[cx][cy][cz] = null;
        }
      }
    }

    // Count solid voxels and pad structure if necessary
    let totalVoxels = 0;
    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        for (let z = 0; z < D; z++) {
          if (world[x][y][z] !== null) totalVoxels++;
        }
      }
    }

    if (totalVoxels < 520) {
      // Reinforce ground footings and under-deck beams to hit quota safely
      for (let x = 2; x <= 8; x++) {
        for (let z = 2; z <= 8; z++) {
          const gy = getGroundY(x, z);
          if (world[x][gy][z] === null) {
            const hasAdj = getNeighbors(x, gy, z).some(([nx, ny, nz]) => world[nx][ny][nz] !== null);
            if (hasAdj) {
              world[x][gy][z] = plinth;
              totalVoxels++;
            }
          }
          if (totalVoxels >= 550) break;
        }
        if (totalVoxels >= 550) break;
      }
    }
  }

  ensureSingleConnectedSolid();

  // --- Output Emission ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = world[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Fish Drying Scaffold",
    seatY: SEAT_Y,
    anchors: {
      front: [5, SEAT_Y, 0],
      deck: [5, 7, 5]
    }
  };
}
